 if(!m)out='Minion groups addon is not initialized. Requires Living Continuity.';
 else if(cmd==='list'){const groups=Object.values(m.capsules??{}).slice(0,25);out='LC MINION GROUPS: '+(groups.length?groups.map(g=>g.id+' ['+g.status+'] '+g.count+' members').join(' | '):'none');}
