const remReverse=(eid,gid)=>{m.reverse[eid]=(m.reverse[eid]??[]).filter(x=>x!==gid)};
const conflict=(g,eid,except)=>g.exclusiveDomain&&edgesFor(eid).some(x=>x.groupId!==except&&x.groupId!==g.id&&m.groups[x.groupId]?.exclusiveDomain===g.exclusiveDomain);
const take=(g,eid,role,ev)=>{let e=m.edges[g.id+'|'+eid];if(e?.active)return fail('already-member');if(Object.keys(g.members).length>=Math.max(1,Number(c.maxMembersPerGroup??4096)))return fail('member-cap');if(conflict(g,eid))return fail('exclusive-domain-conflict');e={id:g.id+'|'+eid,groupId:g.id,entityId:eid,role:str(role)||'member',active:true,source:ev.evidence?.source??'unprovided',joinedAtTick:now,revision:Number(e?.revision||0)+1};m.edges[e.id]=e;g.members[eid]=e.id;addReverse(eid,g.id);g.revision++;return {status:'applied',edgeId:e.id};};
