const process=ev=>{if(!O(ev))return fail('bad-event');const kind=str(ev.type),gid=str(ev.groupId),eid=str(ev.entityId),to=str(ev.toGroupId),g=m.groups[gid];if(c.requireEvidence!==false&&!validEvidence(ev.evidence))return {status:'pending',reason:'requires-confirmed-authority-evidence'};
