   if(g.status!=='active')return fail('group-not-active');if(!m.entities[eid]){if(ev.entityKind==='lc-only'&&c.allowLCOnlyIndividual!==false)m.entities[eid]={id:eid,kind:'lc-only',source:ev.evidence?.source??'unprovided',createdAtTick:now};else if(str(ev.entityKind)==='host-reference'&&ev.hostEntityVerified===true)m.entities[eid]={id:eid,kind:'host-reference',source:ev.evidence?.source??'unprovided'};else return fail('unresolved-entity-reference');}
