  }
  if(kind==='leave')return drop(g,eid,ev.reason);
  const dest=m.groups[to];if(!dest||dest.status!=='active'||!active(gid,eid))return fail('invalid-transfer');if(dest.id===gid||active(to,eid))return fail('already-in-destination');if(Object.keys(dest.members).length>=Math.max(1,Number(c.maxMembersPerGroup??4096)))return fail('destination-full');if(conflict(dest,eid,gid))return fail('exclusive-domain-conflict');const role=ev.role||m.edges[gid+'|'+eid]?.role||'member';drop(g,eid,'transfer:'+to);const result=take(dest,eid,role,ev);return result.status==='applied'?{status:'applied',fromGroupId:gid,toGroupId:to,entityId:eid}:fail('transfer-commit-failed');
 }
 if(kind==='cohortMove'){
  const cid=str(ev.cohortId),dest=m.groups[to],co=g.cohorts[cid],amount=Number(ev.count),newId=str(ev.toCohortId||cid);
