  if(prior){prior.remaining+=amount;prior.initialCount+=amount;}else dest.cohorts[newId]={id:newId,templateId:co.templateId,initialCount:amount,remaining:amount,nextSlot:0,source:ev.evidence?.source??'unprovided'};
  g.revision++;dest.revision++;return {status:'applied',amount,fromGroupId:gid,toGroupId:to};
 }
 if(kind==='cohortLoss'){
